// Generates supabase/tests/database/03_scoring_cases.test.sql from the shared
// scoring fixture, so SQL and TypeScript scoring are verified against the same cases.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const cases = JSON.parse(readFileSync(resolve(root, 'supabase/tests/fixtures/scoring-cases.json'), 'utf8'));

const q = (s) => `'${String(s).replaceAll("'", "''")}'`;
const lines = [
  '-- GENERATED by scripts/gen-scoring-sql-test.mjs from supabase/tests/fixtures/scoring-cases.json',
  '-- Do not edit by hand.',
  'begin;',
  `select plan(${cases.length * 5});`,
  '',
];

for (const c of cases) {
  const m = c.metrics;
  const pp = `public.safe_ratio(${m.pointsAwarded}, ${m.maxPoints})`;
  const cp = `public.safe_ratio(${m.approved}, ${m.assigned})`;
  const tp = `public.safe_ratio(${m.onTime}, ${m.submitted})`;
  const w = q(JSON.stringify(c.weights)) + '::jsonb';
  const base = `public.calc_assessment_score(${pp}, ${cp}, ${tp}, ${c.discretionary}, ${w})`;
  lines.push(`-- ${c.name}`);
  lines.push(`select is(${pp}, ${c.expected.pointsPct}::numeric, ${q(c.name + ': points %')});`);
  lines.push(`select is(${cp}, ${c.expected.completionPct}::numeric, ${q(c.name + ': completion %')});`);
  lines.push(`select is(${tp}, ${c.expected.punctualityPct}::numeric, ${q(c.name + ': punctuality %')});`);
  lines.push(`select is(${base}, ${c.expected.baseScore}::numeric, ${q(c.name + ': base score')});`);
  lines.push(`select is(${base} + ${c.bonus}, ${c.expected.totalScore}::numeric, ${q(c.name + ': total score')});`);
  lines.push('');
}

lines.push('select * from finish();', 'rollback;', '');
writeFileSync(resolve(root, 'supabase/tests/database/03_scoring_cases.test.sql'), lines.join('\n'));
console.log(`Wrote ${cases.length} scoring cases to supabase/tests/database/03_scoring_cases.test.sql`);
